package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Cap;
import net.officefloor.hq.app.setting.DatedSettings;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
 * added up; their due-total those claims' dues (live figures rounded by its policy date, plus
 * any late charge, at the late percent in force on each 30-day boundary, on the overdue ones, then raised to the floor in force on each claim's date) added up, at most the cap in force on the sheet's today; n/a when their grade on the sheet's today has no
 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). Their overdue-total
 * is the dues of their overdue counting claims added up (skipping n/a, not capped). The sheet's totals add these up, skipping n/a;
 * its due-total and overdue-total leave out the single highest and lowest person's figure when three or more have one.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup compute(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.findAll(sheetId);
        DatedSettings dated = settings.dated(sheetId);
        BigDecimal cap = dated.capOn(today);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean kept = false;
            for (Claim claim : sheetClaims) {
                if (claim.personId() != person.id() || !person.counts(claim, today)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                kept |= claim.keepsFigure();
                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
                        dated.floorOn(claim.date()), dated.lateCharge(today), rounding);
                if (figure != null) {
                    kept = true;
                    due = due.add(figure);
                    if (claim.overdue(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
            due = Cap.apply(cap, due);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dues.add(due);
            }
            overdues.add(overdue);
            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due), show(overdue)));
        }
        return new Rollup(figures, show(claimedTotal), show(trimmedTotal(dues)), show(trimmedTotal(overdues)));
    }

    /** The figures added up, leaving out the single highest and single lowest when there are three or more. */
    private static BigDecimal trimmedTotal(List<BigDecimal> values) {
        List<BigDecimal> sorted = new ArrayList<>(values);
        sorted.sort(null);
        if (sorted.size() >= 3) {
            sorted = sorted.subList(1, sorted.size() - 1);
        }
        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import java.util.Map;

/**
 * A sheet's figures at one moment: each person's claimed, due-total and overdue-total (by person id, in the
 * order they were added) and the sheet's claimed-total, due-total and overdue-total, each as shown (two decimals; a due-total may be n/a).
 */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {

    /** A person's name and figures. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {

        /** Whether the figures are the same as the other's, whatever the name. */
        public boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/**
 * A person as the screen shows them; the last statement's due-total and date are null before the first, and
 * {@code retiredFrom} is null while they are not retired; {@code held} is whether they have any hold, {@code holds}
 * each hold, oldest first. {@code grade} is the grade in force on the sheet's today; {@code grades} every grade
 * recorded, each from its from-date. {@code terms} are the person's own terms in days, null when they have none.
 */
public record PersonResponse(long id, String name, String grade, int version, int statementCount, String statedTotal,
        String statementDate, boolean retired, String retiredFrom, boolean held,
        List<Grade> grades, List<HoldDates> holds, Integer terms) {


    /** A grade recorded for the person, from its from-date (yyyy-mm-dd; null: from the beginning of time). */
    public record Grade(String grade, String from) {
    }

    /** A hold on the person, from its from-date to its to-date, both inclusive (yyyy-mm-dd; null: open-ended). */
    public record HoldDates(String from, String to) {
    }

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.id(), person.name(), person.grade(), person.version(), person.statementCount(),
                person.statedTotal(), person.statementDate() == null ? null : person.statementDate().toString(),
                person.retired(), person.retiredFrom() == null ? null : person.retiredFrom().toString(),
                person.held(), person.grades().stream()
                        .map((g) -> new Grade(g.grade(), g.from() == null ? null : g.from().toString())).toList(),
                person.holds().stream().map((h) -> new HoldDates(h.from() == null ? null : h.from().toString(),
                        h.to() == null ? null : h.to().toString())).toList(), person.terms());
    }
}

